cy.visit(`${_constants.default.ABBACO_LOCATION}/curves`);
cy.contains('a.text-link', 'Titulos Privados - C.R.A.s - BRL', {
  matchCase: false
}).should('be.visible').click({
  force: true
});
// Validación del gráfico y los botones del gráfico, en la pestaña "Curva"
cy.get('span.placeholder-glow').should('not.exist');
cy.get('rect[class="highcharts-background"]').should('exist').and('be.visible');
cy.get('path[class="highcharts-tracker-line"]').should('exist').and('be.visible');
cy.get('button.highcharts-a11y-proxy-button').should('exist').and('be.visible');
// Validación de la tabla donde se encuentran las especies de la curva'
cy.get('div.table-responsive').should('exist').and('be.visible');
cy.get('td.text-center').should('not.exist');
cy.get('button.p-0.text-link.border-0.btn.btn-none').last().scrollIntoView().should('be.visible').click({
  force: true
});

cy.contains('Análise Online', {
  matchCase: false
}).should('exist').and('be.visible').click({
  force: true
});
cy.get('div.card').should('be.visible');

cy.contains('Títulos fora da Curva', {
  matchCase: false
}).should('exist').and('be.visible').click({
  force: true
});
cy.get('div.card').should('be.visible');

